var tx = await radio.RequestTxAsync(profile, workId, token);
try
{
    await tx.WaitReadyAsync(timeout, token);
    log.Mark(workId, "ready", tx.ObservedAt);
    await tx.WriteAsync(audioFrames, token);
    await tx.DrainAsync(timeout, token);
}
finally
{
    try
    {
        await tx.ReleaseAsync(CancellationToken.None);
    }
    finally
    {
        queue.Clear(workId);
    }
}
